let current: Promise<void> | undefined;

function search(query: string, render: (items: string[]) => void) {
  current = fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then((r) => r.json() as Promise<string[]>)
    .then(render);
  return current;
}

type Result = { status: string; data?: string; message?: string };

function parseResult(raw: unknown): Result {
  return raw as Result;
}

function display(raw: unknown) {
  const result = parseResult(raw);
  if (result.status === 'success') return result.data!.toUpperCase();
  return result.message!;
}
